INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79559, 'spa', 'Nombre propio: Abidán', 'El nombre propio אֲבִידָן, que designa al hijo de Gedeoni y príncipe tribal de Benjamín durante la peregrinación de Israel por el desierto. Las cinco apariciones se encuentran en Números en registros oficiales: el censo (Nm 1:11), la disposición del campamento (Nm 2:22) y las ofrendas de dedicación del tabernáculo (Nm 7:60, 65; 10:24). El nombre sigue el patrón teofórico hebreo que combina אָב (''padre'') con דִּין (''juez'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79561, 'spa', 'Nombre propio hebreo (אֲבִיָּה / אֲבִיָּהוּ) que significa ''Yah(u) es mi padre'',', 'Nombre propio hebreo (אֲבִיָּה / אֲבִיָּהוּ) que significa ''Yah(u) es mi padre'', compartido por varias personas bíblicas. El más destacado es el rey Abías de Judá, sucesor de Roboam (2 Crónicas 13:1-22), cuyo nombre también aparece como Abiam (1 Reyes 15:1). El turno sacerdotal de Abías (1 Crónicas 24:10) perduró hasta la época del Segundo Templo; Lucas identifica a Zacarías como perteneciente a él (Lucas 1:5). Las traducciones al español generalmente transliteran el nombre como ''Abías''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79566, 'spa', 'Abiú — nombre propio del segundo hijo de Aarón, quien presenció la teofanía en e', 'Abiú — nombre propio del segundo hijo de Aarón, quien presenció la teofanía en el Sinaí (Éx 24:1, 9) y fue consumido por fuego divino por ofrecer incienso no autorizado (Lv 10:1-2). Todas las apariciones designan al mismo individuo, con variación únicamente sintáctica (sustantivo solo o precedido de conjunción).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79569, 'spa', 'Abihail', 'Nombre personal que significa «mi padre es fortaleza», aplicado a múltiples individuos: un levita merarita (Num 3:35), un ancestro gadita (1 Chr 5:14), el padre de Ester (Esth 2:15; 9:29), la esposa de Abisur (1 Chr 2:29) y una esposa de Roboám (2 Chr 11:18). Las variantes ortográficas reflejan la alternancia de la consonante hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79572, 'spa', 'Gentilicio de clan', 'Las traducciones lo presentan como designación étnica o de clan: español «abiezerita», francés «l''Abiézrite», alemán «der Abiesrite». Las tres apariciones en Jueces identifican a la familia de Gedeón como abiezerita, estableciendo sus credenciales tribales dentro de Manasés. Esta designación sitúa a Gedeón dentro de la estructura tribal de Israel: no es un héroe genérico, sino un hombre con linaje específico en el pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79573, 'spa', 'necesitado, pobre, indigente', 'Persona en estado de pobreza material severa y vulnerabilidad social, usado tanto como adjetivo como sustantivo para designar al indigente sujeto a explotación y dependiente de la protección divina y comunitaria. Textos proféticos como Am 2:6 y 8:6 emparejan אֶבְיוֹן con דַּל (''débil'') para condenar la opresión económica, mientras que Dt 15:7-11 legisla la provisión generosa para el necesitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79606, 'spa', 'Nombre propio: Abiyam', 'El nombre propio אֲבִיָּם, que designa al rey de Judá que sucedió a Roboam y precedió a Asa. Esta grafía aparece exclusivamente en 1 Reyes (14:31; 15:1, 7, 8), mientras que el relato paralelo de Crónicas emplea las formas más largas אֲבִיָּהוּ y אֲבִיָּה. La Septuaginta traduce el nombre como Abiou, y las cinco apariciones se refieren a este único monarca davídico cuyo breve reinado se resume como continuación del pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79608, 'spa', 'Abimelec (nombre propio)', 'Nombre propio portado por al menos tres figuras distintas: el rey filisteo de Gerar en las narrativas de Abraham e Isaac (Gn 20-21, 26), el ambicioso hijo de Gedeón que se proclamó rey de Siquem antes de morir por una piedra de molino (Jue 9), y una figura sacerdotal en 1 Cr 18:16. Todas las lenguas conservan el nombre igual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79617, 'spa', 'Abinadab (nombre propio) — nombre propio llevado por varios personajes del AT', 'Abinadab (nombre propio) — nombre propio llevado por varios personajes del AT: el guardián del arca en Quiriat-jearim (1 S 7:1; 2 S 6:3), un hijo de Isaí y hermano de David (1 S 16:8; 17:13), y un hijo de Saúl que cayó en Gilboa (1 S 31:2; 1 Cr 10:2). El nombre se preserva uniformemente en las traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79620, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que identifica al padre de Barac, el comandante israelita en la guerra contra Sísara. Sus cuatro apariciones se encuentran en Jueces 4-5: Jue 4:6 y 4:12 en la narrativa en prosa, y Jue 5:1 y 5:12 en el Cántico de Débora. El nombre se transliterada de forma consistente en las distintas lenguas, conservando su etimología hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79621, 'spa', 'Nombre propio levítico', 'El nombre presenta variación en las traducciones: español «Ebiasaf», francés y alemán conservan la forma hebrea «אביסף». 1 Crónicas 6:23 sitúa a Ebiasaf en la línea levítica coatita. 1 Crónicas 6:37 traza la ascendencia de Hemán el cantor hasta Ebiasaf. 1 Crónicas 9:19 identifica a porteros levíticos como hijos de Coré, descendientes de Ebiasaf. La fidelidad de esta familia en el servicio del templo contrasta con la rebelión de su antepasado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79622, 'spa', 'Abiezer (nombre propio)', 'Abiezer — nombre propio y de clan que significa ''mi padre es ayuda''. Se refiere a (a) el ancestro de un clan manasita con territorio asignado en la tierra (Jos 17:2), cuyo descendiente más célebre es Gedeón (Jue 6:34, ''el Espíritu revistió a Gedeón y los abiezeritas se reunieron''; Jue 8:2), y (b) un guerrero benjaminita en la guardia de élite de David (2 S 23:27; 1 Cr 11:28; 27:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79625, 'spa', 'Poderoso (epíteto divino)', 'Epíteto divino que significa ''Poderoso'', usado exclusivamente en frases constructas (''Poderoso de Jacob'', ''Poderoso de Israel'') para expresar el poder soberano y la fuerza protectora de Dios. Aparece por primera vez en la bendición poética de Jacob (Gen 49:24), reaparece en los Salmos (132:2, 5) y en Isaías (1:24; 49:26; 60:16), siempre en un registro elevado y poético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79628, 'spa', 'Toro o semental poderoso', 'Toro o semental poderoso. Animal fuerte y vigoroso, típicamente un toro o un semental. Los ''toros de Basán'' (Sal 22:13) son enemigos feroces representados como bestias poderosas; en el Salmo 50:13 Dios desestima la carne de los ''poderosos'' (toros) como sacrificio innecesario. Isaías 34:7 lo emplea para los búfalos salvajes en el juicio contra Edom. El referente animal se distingue claramente del humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79629, 'spa', 'Poderoso, guerrero', 'Poderoso, guerrero. Denota a una persona poderosa, guerrero o ser celestial, alguien que posee fuerza o valor extraordinarios. En el Salmo 78:25 se refiere a los ángeles (''pan de los poderosos''), mientras que en Job 24:22 y Jeremías 46:15 describe opresores violentos o combatientes poderosos a quienes Dios derriba. Se usa sustantivado para indicar fuerza cruda ejercida por un agente personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79638, 'spa', 'Obstinado de corazón', 'Obstinado de corazón. En la frase fija אַבִּירֵי לֵב (poderosos de corazón), la palabra pasa de la fuerza física a la obstinación moral: aquellos que son desafiantes e inflexibles ante Dios. Isaías 46:12 se dirige a los ''fuertes de corazón que están lejos de la justicia'', y el Salmo 76:6 describe guerreros tan obstinados que su valentía se convierte en su perdición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79643, 'spa', 'Jefe, líder', 'Jefe, líder. Persona principal o de rango, enfatizando autoridad social más que fuerza física. Este uso poco frecuente aparece en 1 Samuel 21:8, donde Doeg el edomita es descrito como ''jefe'' de los pastores de Saúl. La evidencia multilingüe confirma que se trata de un sentido administrativo distinto, aunque se han propuesto enmiendas textuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79644, 'spa', 'Abiram (nombre propio) — Abiram hijo de Eliab, rubenita que se unió a Datán y Co', 'Abiram (nombre propio) — Abiram hijo de Eliab, rubenita que se unió a Datán y Coré para desafiar la autoridad de Moisés y Aarón. Dios juzgó la rebelión cuando la tierra se abrió y tragó a los conspiradores vivos (Nm 16:1-27). El acontecimiento se conserva como paradigma de juicio divino (Nm 26:9; Dt 11:6; Sal 106:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79649, 'spa', 'Nombre propio femenino', 'Nombre propio que identifica a la joven sunamita que sirvió como acompañante del anciano rey David (1 Re 1:3, 15). La petición de Adonías de tomarla por esposa tras la muerte de David (1 Re 2:17, 21) provocó que Salomón ordenara su ejecución. Las cinco apariciones se refieren a esta única persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79650, 'spa', 'Nombre propio masculino', 'Nombre propio aplicado a dos figuras veterotestamentarias: principalmente el hijo de Finees y bisnieto de Aarón en el linaje sumo sacerdotal (1 Cr 6:4-5, 50; Esd 7:5), y un benjaminita hijo de Bela (1 Cr 8:4). El nombre combina אָב («padre») con שׁוּעַ («salvación, riqueza»). Las cinco apariciones figuran en registros genealógicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79652, 'spa', 'Nombre propio Abisai (אֲבִישַׁי / אַבְשַׁי), que identifica al sobrino de David ', 'Nombre propio Abisai (אֲבִישַׁי / אַבְשַׁי), que identifica al sobrino de David a través de Sarvia, hermano de Joab y Asael, y uno de los ''Tres'' o ''Treinta'' guerreros valientes. Aparece por primera vez en 1 Samuel 26:6 entrando con David de noche al campamento de Saúl. El español ''Abisai'', el francés ''Abischaï'' y el alemán ''Abischai'' transliteran al mismo personaje. La grafía alternativa אַבְשַׁי en Crónicas refleja una variante contraída del mismo nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79657, 'spa', 'Absalón (nombre propio)', 'Nombre propio masculino que significa ''mi padre es paz,'' identificando principalmente al tercer hijo de David, cuya rebelión y muerte se narran en 2 Samuel 13-18 (más de 90 ocurrencias). Un segundo Absalón aparece como padre de Maacá (1 R 15:2, 10). La etimología irónica del nombre —''paz''— contrasta agudamente con los conflictos que definen la historia de este personaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79666, 'spa', 'Nombre propio Abiatar, que designa al sacerdote que escapó de la masacre de Saúl', 'Nombre propio Abiatar, que designa al sacerdote que escapó de la masacre de Saúl en Nob y se convirtió en el leal compañero sacerdotal de David. Se le asocia con el efod utilizado para la consulta divina (1 Samuel 23:6, 9; 30:7) y sirvió junto a Sadoc durante el reinado de David (2 Samuel 15:35; 20:25). Su destitución por Salomón (1 Reyes 2:26-27) marca el fin de la línea sacerdotal de Elí y el ascenso del sacerdocio sadoquita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79677, 'spa', 'Duelo en Qal', 'Duelo en Qal: estado intransitivo de aflicción o languidez, aplicado a personas, la tierra o elementos de la creación. Las puertas de Isaías ''se enlutan'' (3:26), la tierra se seca y llora (Isaías 24:4; Oseas 4:3; Joel 1:10) y los pescadores se lamentan (Isaías 19:8). Este uso tiende un puente entre el duelo humano literal y la personificación poética, presentando la creación como partícipe del dolor de la comunidad del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79680, 'spa', 'Duelo en Hitpael', 'Duelo en Hitpael: expresiones externas y demostrativas de dolor realizadas por un doliente. Jacob hizo duelo muchos días por José (Génesis 37:34), Esdras se lamentó por la infidelidad de los exiliados (Esdras 10:6) y Nehemías se sentó, lloró y guardó luto durante días (Nehemías 1:4). La raíz reflexivo-intensiva señala acciones visibles: llanto, ayuno y vestir cilicio. El español ''hacer duelo'' y ''enlutarse'' captan este matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79693, 'spa', 'Hifil causativo', 'Hifil causativo: hacer lamentar o provocar duelo sobre alguien o algo. En Lamentaciones 2:8, el SEÑOR hizo lamentar a la muralla y al muro, y en Ezequiel 31:15, Dios hizo que el abismo guardara luto por la caída del gran cedro de Asiria. Solo dos ocurrencias conservan esta raíz causativa, pero ambas tienen un peso teológico considerable: Dios como agente que impone el duelo sobre el orden creado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79707, 'spa', 'Enlutado, afligido', 'En estado de duelo o aflicción, usado como adjetivo o sustantivo para quien se lamenta por muerte, calamidad o pérdida nacional. Jacob llora por José sin consuelo (Gn 37:35); el salmista camina abatido ''como quien llora por un amigo'' (Sal 35:14). Isaías amplía el alcance al duelo escatológico por Sion (Is 57:18; 61:2-3), donde Dios promete consolar a los enlutados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79714, 'spa', 'Topónimo septentrional', 'Nombre propio de lugar que designa una ciudad en el norte de Israel, conocida más completamente como Abel Bet Maacá. En 2 S 20:14-18, Joab persigue al rebelde Seba hasta esta ciudad amurallada, donde una «mujer sabia» interviene célebremente para salvar su pueblo negociando la ejecución del rebelde. La referencia en 1 S 6:18 es textualmente incierta, y muchos estudiosos enmiendan אָבֵל (pradera) por אֶבֶן (piedra).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79715, 'spa', 'Período o expresión de dolor que abarca tanto los ritos formales como el peso em', 'Período o expresión de dolor que abarca tanto los ritos formales como el peso emocional del duelo. Se aplica al luto por los muertos: los siete días de duelo en Abel-mizraim por Jacob (Génesis 50:10-11), los treinta días de lamentación por Moisés (Deuteronomio 34:8) y la supresión de los ritos de luto que Dios ordena a Ezequiel por su esposa (Ezequiel 24:17). También se usa para el dolor colectivo ante calamidades nacionales: el luto de Ester por el decreto contra los judíos y las fórmulas proféticas de inversión donde Dios convierte el duelo en gozo (Jeremías 31:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79729, 'spa', 'Conjunción adversativa que significa ''pero'', ''sin embargo'' o ''no obstante'', intr', 'Conjunción adversativa que significa ''pero'', ''sin embargo'' o ''no obstante'', introduciendo contraste, matización o concesión. Este es el uso hebreo tardío predominante en textos postexílicos. A Josafat se le dice que a pesar de su falta, ''sin embargo se han hallado cosas buenas en ti'' (2 Cr 19:3). Esdras reconoce la temporada de lluvias pero insiste en que el pueblo no puede quedarse afuera (Esd 10:13). Daniel 10:7, 21 también emplea este sentido adversativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79730, 'spa', 'Adverbio aseverativo que significa ''ciertamente'', ''en verdad'' o ''de veras'', usad', 'Adverbio aseverativo que significa ''ciertamente'', ''en verdad'' o ''de veras'', usado para afirmar con énfasis. Este es el uso hebreo más antiguo encontrado en las narraciones patriarcales y monárquicas. Los hermanos de José confiesan: ''Ciertamente somos culpables con respecto a nuestro hermano'' (Gn 42:21). Dios corrige a Abraham: ''No, sino que Sara tu esposa te dará un hijo'' (Gn 17:19, donde la aseveración se matiza en una corrección suave).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79738, 'spa', 'Topónimo bíblico', 'Las traducciones conservan el nombre propio: en español ''Abel-Mejolah'' o ''Avel-Mejolah''. En Jueces 7:22 sirve como referencia geográfica en la retirada madianita. En 1 Reyes 4:12 se sitúa en el sistema de distritos de Salomón. En 1 Reyes 19:16 se identifica como el hogar de Eliseo, dándole relevancia profética a esta ciudad del valle del Jordán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79741, 'spa', 'piedra, roca (material)', 'Trozo de roca como objeto físico: empleado para construir muros y altares, arrojar como arma, erigir como estela conmemorativa, pavimentar caminos o servir de materia prima. Este sentido abrumadoramente dominante (267 veces) cubre singular y plural, estado constructo y absoluto, con preposiciones y sufijos. La piedra-almohada de Jacob en Betel (Gn 28:11), las tablas de piedra del Sinaí (Ex 24:12) y las piedras de honda son ejemplos representativos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79763, 'spa', 'pesa, piedra de balanza', 'Piedra empleada como pesa estándar para medir en el comercio, la ''piedra de balanza'' (אֶבֶן מִשְׁקָל). Levítico 19:36 ordena ''balanzas justas, pesas justas,'' y Deuteronomio 25:13-15 prohíbe tener dos ''piedras'' diferentes en la bolsa —una grande y una pequeña. El salto metonímico de piedra física a unidad de medida es natural; las pesas antiguas eran literalmente piedras talladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79782, 'spa', 'piedra preciosa', 'La piedra como material precioso o costoso en contextos de honra u ornamento, como en Daniel 11:38, donde se honra a un dios extraño ''con piedra'' —es decir, con piedras preciosas y ofrendas costosas. La frase preposicional ''y con piedra'' (וּבְאֶבֶן) designa aquí material de calidad gema más que roca común, lectura respaldada por el paralelismo con oro y plata en el mismo versículo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79790, 'spa', 'Piedra de Israel (título divino)', 'Uso figurado o titular: ''la Piedra de Israel'' (אֶבֶן יִשְׂרָאֵל) en Génesis 49:24, epíteto divino para Dios como fundamento inamovible y protector de su pueblo. Esta extensión metafórica —de roca física a título teológico— encuentra eco en pasajes posteriores (Is 28:16, Sal 118:22). El sentido se distingue de los demás por su dimensión exclusivamente simbólica y su contexto poético-profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79793, 'spa', 'Piedra (arameo)', 'Sustantivo arameo que designa tanto un material de construcción como un objeto visionario de origen divino. En Esdras 5:8 y 6:4, se refiere a las grandes piedras labradas para la reconstrucción del templo de Jerusalén: tres hileras de piedra y una de madera. En Daniel 2:34-35 y 45, denota la piedra sobrenatural ''cortada sin manos'' que destruye los reinos humanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79797, 'spa', 'Piedra conmemorativa', 'Las traducciones preservan el nombre propio: en español ''Eben-Ezer'' o ''Even-Ezer''. En 1 Samuel 4:1 y 5:1 se asocia con la derrota de Israel y la captura del arca. Pero 1 Samuel 7:12 redime el nombre cuando Samuel erige una piedra memorial declarando la ayuda del Señor. El contraste entre derrota y victoria en el mismo lugar subraya la fidelidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79798, 'spa', 'Faja sacerdotal', 'Faja sacerdotal tejida que se ceñía a la cintura sobre la túnica durante el servicio en el tabernáculo y el templo. Prescrita tanto para el sumo sacerdote (Éx 28:4, 39; Lv 8:7; 16:4) como para los sacerdotes ordinarios (Éx 28:40; 29:9; Lv 8:13), y extendida metafóricamente a un alto funcionario en Isaías 22:21, donde Eliaquim recibe la faja como símbolo de investidura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79805, 'spa', 'Abner (nombre propio)', 'Nombre propio del primo de Saúl y comandante de su ejército, hijo de Ner (1 S 14:50-51). Figura clave en la sucesión tras la muerte de Saúl: defiende a Is-boset (2 S 2:8), negocia su paso a David (2 S 3:12) y es asesinado por Joab (2 S 3:27). Aparece en grafía corta (Abner) y larga (Abiner).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79819, 'spa', 'Polvo fino', 'Polvo fino o partículas suspendidas, especialmente las levantadas por el viento, los pies o la combustión, distintas del más genérico afar (''tierra, polvo del suelo''). En Éxodo 9:9 es el hollín del horno convertido en plaga, y en Deuteronomio 28:24 (paralelo con afar) cae como lluvia maldita. Isaías lo emplea como imagen de destrucción súbita y total (5:24; 29:5), mientras Nahúm 1:3 lo usa figuradamente para las nubes como polvo bajo los pies de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79825, 'spa', 'Alas y plumaje', 'Las traducciones reflejan tanto la dimensión literal como la metafórica: en español ''ala'', ''alas'', ''plumaje''. El Salmo 55:6 usa las alas como metáfora de huida y libertad. Isaías 40:31 emplea las alas de águila como imagen de fortaleza renovada por Dios. Ezequiel 17:3 personifica a Babilonia como un águila de grandes alas, simbolizando alcance y poderío imperial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79826, 'spa', 'Plumas de vuelo', 'Las grandes plumas o plumones del ala de un ave, empleados como imagen poética de protección y vuelo poderoso. En Dt 32:11 el águila «extiende sus plumas» sobre sus crías, símil del cuidado de Dios durante el peregrinaje por el desierto. Sal 91:4 intensifica la metáfora: «bajo sus plumas hallarás refugio», en paralelismo sinonímico con כָּנָף (ala).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79827, 'spa', 'Abram / Abraham (nombre propio)', 'El patriarca originalmente llamado Abram (''padre exaltado''), renombrado Abraham por mandato divino en el pacto de la circuncisión (Gn 17:5). Un solo referente a lo largo de sus 175 ocurrencias, apareciendo en diversos marcos gramaticales —nominativo, con preposiciones y conjunciones. El nombre se extiende desde el relato de la vocación (Gn 12) hasta la memoria postexílica (Neh 9:7). Todas las lenguas meta preservan el nombre como préstamo directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79835, 'spa', 'Abram (nombre propio)', 'Nombre propio masculino del patriarca antes de ser renombrado Abraham en Génesis 17:5. Probablemente significa ''padre exaltado'' (de אָב + רָם), y sus 61 apariciones se agrupan en Génesis 11-17, con menciones retrospectivas en 1 Crónicas 1:27 y Nehemías 9:7. La uniformidad interlingüística es total — Abram en español, francés y alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79840, 'spa', 'Topónimo del desierto', 'Nombre propio de una estación en la ruta del peregrinaje de Israel por el desierto, situada en la frontera oriental de Edom, cerca de Moab. El nombre, que significa ''odres'', podría reflejar la relación del sitio con el almacenamiento de agua en una zona árida. Aparece en Nm 21:10-11 dentro del relato de viaje y en Nm 33:43-44 en el resumen del itinerario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79842, 'spa', 'Agag (nombre propio)', 'Agag, nombre propio del rey amalecita cuya captura y perdón por parte de Saúl provocó la ruptura entre Saúl y Dios (1 S 15:8–9, 20, 32–33). El nombre aparece por primera vez en la profecía de Balaam como símbolo de poderío real que el futuro rey de Israel superará (Nm 24:7). En el relato de Samuel, el fracaso de Saúl en destruir a Agag se convierte en la ocasión de su rechazo como rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79844, 'spa', 'Gentilicio de Amán', 'Adjetivo gentilicio que significa «el agagueo», usado exclusivamente como epíteto de Amán en el libro de Ester (3:1, 10; 8:3, 5; 9:24). La designación probablemente vincula su linaje con Agag, el rey amalecita de 1 Samuel 15, presentando el conflicto de Purim como una continuación de la antigua enemistad entre Israel y Amalec. Josefo (Ant. xi.6.5) confirma esta identificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79845, 'spa', 'Manojo, atadura o bóveda', 'Manojo, atadura, tropa o bóveda: cualquier cosa ligada o reunida en una unidad. La amplitud semántica se refleja en las traducciones: ''manojo de'' (hisopo, Éx 12:22), ''las ataduras del'' (opresión, Is 58:6), ''banda'' (tropa, 2 S 2:25) y ''bóveda'' (cielo, Am 9:6). Todos los usos comparten la raíz conceptual de sujetar o ensamblar elementos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79851, 'spa', 'Estanque, laguna', 'Estanque o laguna de agua quieta, ya sea natural o artificial. Las traducciones multilingües confirman este sentido primario: el español emplea «estanque» y el inglés «pool». Aparece en el contexto de las plagas de Egipto (Éx 7:19; 8:5) y en la imaginería profética de la transformación divina donde el desierto se convierte en estanque de aguas (Sal 107:35; 114:8; Is 41:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79858, 'spa', 'Pantano, ciénaga', 'Pantano o ciénaga, zona anegada y cenagosa distinta de un estanque limpio. Atestiguado en Jeremías 51:32 y contextualmente en Ezequiel 47:11, donde los pantanos y ciénagas no serán sanados por el río vivificante del templo. Esta acepción representa una extensión semántica del estanque quieto hacia el terreno fangoso e inundado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79860, 'spa', 'Junco o espadaña', 'Planta alta de humedal cuyas fibras se usaban para cuerdas y cuyos tallos secos servían como combustible. En Job 41:2 Dios pregunta si se puede pasar una cuerda de juncos por la nariz de Leviatán. Isaías 58:5 emplea la imagen de inclinar la cabeza «como un junco» para describir humildad fingida. Metafóricamente representa lo humilde e insignificante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79861, 'spa', 'Vasija o tazón', 'Las traducciones reflejan usos literales y figurados: en español ''copa'', ''vasijas'', ''tazas''. Éxodo 24:6 describe vasijas rituales con sangre sacrificial durante la institución del pacto. Cantar de los Cantares 7:2 usa el ''tazón redondo'' como imagen de belleza física plena y perfecta. Isaías 22:24 emplea las vasijas metafóricamente para representar descendencia y legado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79862, 'spa', 'Banda, horda, tropas', 'Bandas, hordas o tropas militares que forman el séquito armado de un líder — préstamo del acadio agappu (''ala de un ejército''), usado exclusivamente en Ezequiel para describir las vastas fuerzas militares que acompañan a gobernantes e invasores. Describe las tropas dispersas del rey de Judá (Ez 12:14; 17:21), las hordas de Gomer y Bet-togarmá aliadas con Gog (Ez 38:6), y la abrumadora fuerza invasora de Gog (Ez 38:9, 22; 39:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79866, 'spa', 'Recolectar o cosechar', 'Las traducciones coinciden en el sentido de recoger o recolectar: en español ''recoge'', ''recogerás'', ''el que recoge''. Deuteronomio 28:39 advierte sobre maldiciones del pacto donde el trabajo no produce cosecha que recoger. Proverbios 6:8 encomia la recolección instintiva de la hormiga durante la siega. Proverbios 10:5 contrasta la diligencia con la pereza según el momento de la cosecha.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79867, 'spa', 'Carta oficial', 'El termino arameo aparece en Esdras 4:8 introduciendo correspondencia hostil contra la reconstruccion de Jerusalen, en Esdras 4:11 presentando el contenido de la carta con acusaciones de rebelion, y en Esdras 5:6 registrando la consulta mas neutral de Tatnai al rey Dario. Las traducciones varian: en espanol ''carta,'' en frances e ingles ''lettre/letter,'' en aleman preservando la forma aramea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79870, 'spa', 'Carta o epístola formal, específicamente correspondencia real u oficial del perí', 'Carta o epístola formal, específicamente correspondencia real u oficial del período postexílico. Se usa para la convocatoria pascual de Ezequías (2 Cr 30:1, 6), las cartas de salvoconducto de Nehemías otorgadas por Artajerjes (Neh 2:7-9), las cartas amenazantes recibidas por Nehemías (Neh 6:5, 17, 19) y los despachos cruciales en Ester que decretan y luego revierten la destrucción de los judíos (Est 9:20, 26, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79881, 'spa', 'señor, superior humano', 'Tratamiento respetuoso o referencia a una figura de autoridad humana: rey, esposo, comandante o superior social. Es con diferencia el uso más frecuente (249 veces), funcionando como el árabe سَيِّدِي o el español ''mi señor.'' El término expresa subordinación y deferencia tanto en el discurso directo (Gn 23:6 ''señor mío, escúchanos'') como en la referencia narrativa. La evidencia interlingüística confirma el registro honorífico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79886, 'spa', 'amo, dueño de siervos', 'El propietario o patrón que ejerce autoridad sobre siervos, esclavos o bienes, enfatizando posesión y control más que mera cortesía social. Eliezer llama a Abraham ''su señor'' (Gn 24:9-10), y Potifar es el אָדוֹן de José (Gn 39:2-3). El árabe سَيِّدُهُ (''su amo'') y el alemán sein Herr captan este matiz posesivo. La relación es jurídica y económicamente definida, no meramente ceremonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79888, 'spa', 'el Señor, soberano divino', 'Título divino que se refiere a Dios como Señor soberano, a menudo marcado por el artículo o en contextos teológicos elevados. Los masoretas distinguieron este uso mediante una vocalización especial (Adonai), y los traductores universalmente lo escriben con mayúscula: inglés ''the Lord,'' francés le Seigneur, suajili Bwana. La invocación de Abraham en Gn 18:3 y la fórmula litúrgica ''el Señor, Señor de toda la tierra'' son ejemplos paradigmáticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79897, 'spa', 'señores, amos (plural)', 'La forma plural que denota múltiples señores, amos o gobernantes humanos que ejercen autoridad colectiva. Deuteronomio 10:17 emplea el superlativo ''Señor de señores'' (אֲדֹנֵי הָאֲדֹנִים), mientras que Isaías 26:13 lamenta ''otros señores además de ti se han enseñoreado de nosotros.'' Los plurales fractos árabes y el suajili mabwana reflejan el mismo patrón morfológico para expresar pluralidad de autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79942, 'spa', 'entonces', 'Adverbio temporal arameo que significa ''entonces, en aquel momento, acto seguido.'' Las 57 apariciones se encuentran exclusivamente en las secciones arameas de Esdras (4-7) y Daniel (2-7). El español ''entonces'' capta con precisión la fuerza secuencial-consecutiva. La palabra típicamente abre una nueva cláusula narrativa, señalando que lo que sigue es respuesta directa o resultado de la acción precedente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79944, 'spa', 'Usado como sustantivo para nobles, jefes o líderes de un pueblo, aquellos que os', 'Usado como sustantivo para nobles, jefes o líderes de un pueblo, aquellos que ostentan autoridad social. El cántico de Débora celebra a los nobles que marcharon con ella (Jueces 5:13, 25), Nehemías nombra a los nobles que se negaron a trabajar (Nehemías 3:5) y a los que sellaron el pacto (Nehemías 10:29), y Jeremías se dirige a los ''poderosos del rebaño'' como gobernantes condenados (Jeremías 25:34-36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79945, 'spa', 'Adjetivo de majestad, esplendor y gloria, aplicado a Dios, su nombre y fenómenos', 'Adjetivo de majestad, esplendor y gloria, aplicado a Dios, su nombre y fenómenos naturales o regios imponentes. El Salmo 8:1, 9 enmarca su himno con ''¡cuán majestuoso es tu nombre en toda la tierra!'', el Salmo 93:4 declara a YHWH más majestuoso que las aguas caudalosas, y el Salmo 76:4 alaba a Dios como glorioso desde los montes de caza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79950, 'spa', 'Adjetivo o sustantivo que enfatiza la fuerza bruta y el poderío', 'Adjetivo o sustantivo que enfatiza la fuerza bruta y el poderío: la fuerza abrumadora de aguas caudalosas, naciones poderosas o dioses temibles. Las aguas del Mar Rojo son ''addir'' (Éxodo 15:10), los filisteos tiemblan ante ''dioses poderosos'' (1 Samuel 4:8) y Ezequiel describe la caída de Egipto entre naciones poderosas (Ezequiel 32:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79968, 'spa', 'Participio pasivo del Pu''al', 'Participio pasivo del Pu''al: haber sido teñido o enrojecido mediante un proceso artificial. Se usa exclusivamente de las pieles de carnero preparadas para el Tabernáculo (Ex 25:5; 26:14; 35:7, 23; 36:19; 39:34) y los escudos enrojecidos de Nahúm (Nah 2:4). Indica uniformemente un color aplicado externamente, distinguiendo materiales elaborados de la rojez natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79969, 'spa', 'Sentido activo/estativo en los troncos Qal, Hitpa''el y Hif''il', 'Sentido activo/estativo en los troncos Qal, Hitpa''el y Hif''il: ser o ponerse rojo como cualidad inherente o proceso natural. El Qal perfecto describe la tez rubicunda de los nazareos de Jerusalén antes de la hambruna (Lm 4:7), el Hitpa''el imperfecto capta el vino enrojeciéndose en la copa como tentación visual (Pr 23:31), y el Hif''il imperfecto retrata pecados que ''muestran rojez como el carmesí'' pero pueden ser lavados (Is 1:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79974, 'spa', 'hombre, ser humano', 'Un ser humano individual o ''hombre'' en sentido genérico (cualquier persona, alguien), cubriendo la gran mayoría de las ocurrencias (527 veces). Funciona en textos legales (''si un hombre trae una ofrenda,'' Lv 1:2), sabiduría proverbial (''bienaventurado el hombre,'' Sal 1:1) y narrativa. Se distingue de אִישׁ por su enfoque a nivel de especie: no ''un varón'' sino ''un humano.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79982, 'spa', 'humanidad (colectivo)', 'La humanidad o el género humano considerado como categoría o especie colectiva (19 ocurrencias). Aparece en contextos de alcance universal o de dominio: ''cualquier hombre'' en el sentido de ''cualquier mortal'' (Jue 16:7, 11, 17), o gobernantes puestos ''sobre la humanidad'' (2 S 23:3). Las glosas multilingües emplean construcciones como ''entre la humanidad'' y ''de entre hombre,'' señalando la lectura colectiva más que individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (79986, 'spa', 'Adán (nombre propio)', 'El nombre propio ''Adán,'' referido al primer hombre en el relato de la creación del Génesis (6 ocurrencias). Se identifica por el uso anartro en contextos genealógicos y narrativos: Gn 5:1-2 (''el libro de las generaciones de Adán''), Gn 2:20, 3:21. El árabe آدَم y el coreano 아담 transliteran de forma consistente el nombre. La frontera entre el sustantivo común y el nombre propio es célebremente difusa en los primeros capítulos del Génesis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80018, 'spa', 'El nombre propio Adán, el primer ser humano en la narrativa bíblica', 'El nombre propio Adán, el primer ser humano en la narrativa bíblica. Dios forma a Adán del polvo de la tierra (''adamah'') y lo coloca en el Edén (Gn 2:7-8). Tras la caída, Dios se dirige a él directamente: ''Y al hombre dijo...'' (Gn 3:17). Las genealogías trazan la descendencia desde Adán a través de Set (Gn 4:25; 5:1-5), y 1 Crónicas 1:1 abre su linaje con su nombre. Oseas 6:7 invoca a Adán como arquetipo de la transgresión del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80020, 'spa', 'Topónimo que designa la ciudad de Adán, ubicada cerca del río Jordán junto a Sar', 'Topónimo que designa la ciudad de Adán, ubicada cerca del río Jordán junto a Saretán. En Josué 3:16 las aguas que fluían río abajo ''se detuvieron, levantándose en un solo montón, muy lejos, en Adán, la ciudad junto a Saretán'', permitiendo el cruce milagroso de Israel. La doble aparición en el mismo versículo (una como nombre de la ciudad, otra en la frase locativa) subraya la especificidad geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80023, 'spa', 'Rojo, rojizo (color)', 'Rojo o rojizo en color — un adjetivo cromático directo aplicado a diversos referentes físicos: la tez atractiva de una persona (Cnt 5:10, ''mi amado es blanco y rojizo, señalado entre diez mil''), la vaca alazana prescrita para la purificación (Nm 19:2), agua que aparentaba ser roja como sangre (2 R 3:22), vestiduras teñidas de carmesí por pisar el lagar (Is 63:2), y los caballos rojos de la visión de Zacarías (Zac 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80027, 'spa', 'Edom (persona y nación)', 'El nombre propio Edom, de la raíz א-ד-ם (''rojo''), dado a Esaú tras ceder su primogenitura por un guiso de lentejas rojas (Gn 25:30). Se extiende a sus descendientes como pueblo (Nm 20:18-21; 1 S 14:47), a su territorio montañoso al sureste del Mar Muerto (Gn 32:3; 36:9) y al rey que los representa (Nm 20:18). En el discurso profético, Edom se vuelve emblema de la oposición a Israel, sujeto de oráculos de destrucción que proyectan significado escatológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80036, 'spa', 'Piedra preciosa roja', 'Las traducciones varian: en espanol ''cornerina, rubi,'' en ingles ''ruby,'' en aleman ''Rubin.'' Exodo 28:17 y 39:10 ubican esta piedra en primer lugar en el pectoral sacerdotal, simbolizando una tribu de Israel. Ezequiel 28:13 la incluye en la suntuosa descripcion del estado edenico del rey de Tiro, evocando esplendor y gloria originales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80037, 'spa', 'Rojizo, de tinte rojo', 'Rojizo o de tinte rojizo, describiendo el color de erupciones cutáneas sospechosas examinadas por los sacerdotes bajo el código de pureza levítico. Las seis apariciones se encuentran en Lev 13:19-49 y 14:37, aplicadas a hinchazones, costras, manchas brillantes, marcas en vestiduras y paredes que podrían indicar impureza ceremonial. La forma reduplicativa (אֲדַמְדָּם) transmite un rojo aproximado o atenuado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80038, 'spa', 'Ciudad cananea destruida', 'Nombre propio de una ciudad cananea en el valle de Sidim, destruida por juicio divino junto con Sodoma y Gomorra. Aparece en la Tabla de las Naciones (Gn 10:19), en la batalla de los reyes (Gn 14:2, 8), como ejemplo de maldición del pacto (Dt 29:23) y en la conmovedora pregunta retórica de Dios sobre Efraín (Os 11:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80039, 'spa', 'tierra, territorio', 'Tierra cultivable, territorio, patria: el sentido dominante y más amplio (210 ocurrencias). Abarca tanto el suelo arable de Gn 2:5, 9 como el territorio nacional prometido en el lenguaje deuteronómico de alianza (''la adamah que YHWH juró a vuestros padres,'' Dt 7:13; 28:11). En el uso profético se vuelve virtualmente sinónimo de ''tierra de Israel.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80047, 'spa', 'suelo, polvo (materia)', 'La sustancia física de la tierra —suelo, arcilla, polvo— vista como materia prima. Dios forma a adam del עָפָר מִן־הָאֲדָמָה (polvo de la tierra, Gn 2:7), y Naamán se lleva dos cargas de adamah israelita a Siria (2 R 5:17). El contraste en Ex 20:24 (''un altar de adamah'') confirma esta lectura material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80059, 'spa', 'superficie del suelo', 'La superficie del suelo como referencia espacial: el plano bajo los pies donde las cosas caen, se arrastran o reposan. En Gn 4:2, Lv 20:25 y Dt 4:18 designa la superficie terrestre como hábitat de animales rastreros, distinta del sentido territorial y del material. El Sal 104:30 la emplea para la faz renovada de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80077, 'spa', 'tierras de cultivo', 'Tierras de labranza o campos arables como designación agrícola específica, más restringida que el sentido territorial amplio. En Sal 105:35 las langostas devoran ''toda la vegetación de su adamah,'' e Is 1:7 describe a extranjeros consumiendo ''vuestra adamah.'' Las construcciones posesivas (''su suelo,'' ''vuestro suelo'') lo marcan como superficie cultivada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80086, 'spa', 'tierras, heredades', 'Forma plural poco frecuente (adamot) que significa ''tierras'' o ''heredades'': en Sal 49:11 los ricos ponen ''su nombre a sus adamot.'' El plural sugiere parcelas distintas o propiedades territoriales en vez del concepto singular de tierra o patria. Probablemente se trata de una especialización contextual del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80089, 'spa', 'Edomita (gentilicio) — persona perteneciente a Edom, la nación descendiente de E', 'Edomita (gentilicio) — persona perteneciente a Edom, la nación descendiente de Esaú. Se aplica notablemente a Doeg el edomita (1 S 21:7; 22:9, 18; título del Sal 52), a las mujeres edomitas (1 R 11:1) y en el mandato de no aborrecer al edomita (Dt 23:7). Un único sentido gentilicio con variación de número, género y forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80095, 'spa', 'Rojizo o rubicundo', 'Las traducciones reflejan tanto el color rojo como la tez rubicunda: en espanol ''rojizo,'' en ingles ''red, ruddy,'' en aleman ''rotlich.'' Genesis 25:25 enfatiza el inusual enrojecimiento de Esau al nacer, vinculandolo al nombre Edom. En 1 Samuel 16:12 se describe la buena apariencia rubicunda de David cuando Samuel lo unge, senalando juventud y salud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80097, 'spa', 'basa o pedestal', 'Sentido técnico principal (55 veces): basa o pedestal metálico empleado en la construcción del Tabernáculo. Cada tablón requería dos basas de plata (Éx 26:19-21), y cada columna una basa de bronce, sumando cerca de cien para toda la estructura. El resumen de Éxodo 38:27 contabiliza cien basas fundidas de un talento de plata cada una.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80105, 'spa', 'fundamento, cimiento', 'Sentido arquitectónico o cosmológico extendido (2 veces), referido a fundamentos de estructuras mayores. En Job 38:6, Dios pregunta quién puso los אַדְנֵי de la tierra — sus pedestales de cimiento — evocando arquitectura cósmica. En Cantares 5:15, las piernas del amado descansan sobre אַדְנֵי פָז (''pedestales de oro fino''), trasladando la imagen sacra a la belleza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80109, 'spa', 'Señor (título divino)', 'El título divino Adonai, empleado 440 veces para dirigirse o referirse a Dios como Señor soberano. Incluye invocaciones en oración directa (Gn 15:2, ''Oh Señor YHWH, ¿qué me darás?''), apelaciones proféticas (Dt 3:24) y declaraciones litúrgicas. La forma intensiva del plural con sufijo de primera persona (אֲדֹנָי) señala majestad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80115, 'spa', 'señor (superior humano)', 'Un señor, amo o superior humano al que se trata con deferencia; aparece solo 5 veces. Se usa con sufijos pronominales (''mi señor,'' ''su señor'') para expresar jerarquía social o mando militar: el jefe del ejército de YHWH (Jos 5:14), el ''Señor de toda la tierra'' (Jos 3:11, 13) y la fórmula autodeprecativa de Gedeón (Jue 6:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80131, 'spa', 'Rey cananeo', 'El nombre se traduce uniformemente como ''Adoni-Bezec'' en todas las lenguas. Jueces 1:5 lo presenta como el rey hallado en Bezec. Jueces 1:6 describe su captura tras huir de la batalla. Jueces 1:7 registra su confesion de haber mutilado a setenta reyes, reconociendo la retribucion divina: tal como el habia obrado, Dios le pago.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80132, 'spa', 'Nombre propio Adonías que designa al cuarto hijo de David, cuyo intento fallido ', 'Nombre propio Adonías que designa al cuarto hijo de David, cuyo intento fallido de reclamar el trono antes de la unción de Salomón se narra en 1 Reyes 1-2. Casi las 24 ocurrencias se concentran en esta narrativa de sucesión. Las glosas multilingües añaden consistentemente preposiciones que reflejan las alineaciones políticas del relato: quién estaba ''a favor de'' o ''con'' Adonías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80135, 'spa', 'El mismo nombre portado por otros dos individuos', 'El mismo nombre portado por otros dos individuos: un levita comisionado por el rey Josafat para enseñar la Torá por todo Judá (2 Cr 17:8), y un jefe de clan identificado con la familia de Adonicam que selló el pacto de Nehemías (Neh 10:17; cf. Esd 2:13). Solo 2 ocurrencias corresponden aquí; las glosas en francés y alemán enmarcan la forma hebrea [אדניה] señalando referentes menos conocidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80140, 'spa', 'Nombre teoforico', 'Las traducciones preservan el nombre: en espanol ''Adonicam,'' en ingles ''Adonikam.'' Esdras 2:13 numera a los miembros de esta familia en 666 (o 667), un clan considerable. Esdras 8:13 registra a otros miembros uniendose a la caravana de Esdras, incluyendo lideres con nombre propio. Nehemias 7:18 confirma la prominencia de la familia en la restauracion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80142, 'spa', 'Esplendor divino', 'Las traducciones reflejan reverencia por la majestad divina: «gloriosa, glorioso» en español, «majestic» en inglés y formas similares en otros idiomas. Éxodo 15:6 celebra la diestra gloriosa de Dios que quebrantó al enemigo en el mar. Éxodo 15:11 adora al Dios majestuoso en santidad, incomparable entre todos. Isaías 42:21 declara que Dios engrandecerá y hará gloriosa su ley por amor a su justicia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80143, 'spa', 'Adar (mes hebreo)', 'Adar, el duodécimo mes del calendario babilónico-judío (aproximadamente febrero–marzo), préstamo del acadio «Addaru». Todas sus apariciones están en Ester, donde funciona como marcador temporal de profunda significación teológica: la suerte (pur) de Amán cae en Adar para el genocidio planeado (Est 3:7, 13), pero Dios revierte el decreto y los judíos triunfan el día 13 de Adar, celebrándolo como Purim.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80152, 'spa', 'Deidad y persona', 'Las traducciones conservan el nombre: «Adramelec» o «Adramélec» en español, «Adrammelech» en inglés y formas similares en otros idiomas. 2 Reyes 17:31 identifica a Adramelec como un dios al cual los sefarvitas quemaban a sus hijos, paganismo sincretista trasplantado a Israel. 2 Reyes 19:37 e Isaías 37:38 nombran a Adramelec como el hijo parricida de Senaquerib que mató a su padre mientras este adoraba en su templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80154, 'spa', 'Edrei (topónimo)', 'Edrei, ciudad fortificada en Basán donde Israel derrotó al rey Og en una batalla decisiva durante el período del desierto (Nm 21:33; Dt 3:1). Citada junto a Astarot como una de las dos capitales reales de Og (Dt 1:4; Jos 12:4; 13:12), fue asignada a la media tribu de Manasés (Jos 13:31). Una ciudad distinta con el mismo nombre aparece en el territorio tribal de Neftalí (Jos 19:37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80158, 'spa', 'Manto, capa, vestidura — vestidura exterior grande e imponente', 'Manto, capa, vestidura — vestidura exterior grande e imponente. La piel velluda de Esaú al nacer se compara con un ''manto de pelo'' (Gn 25:25). Acán codició un fino manto babilónico (Jos 7:21, 24). Es ante todo el manto profético de Elías, envuelto alrededor de su rostro ante Dios en el Horeb (1 R 19:13), echado sobre Eliseo (1 R 19:19) y usado para golpear el Jordán (2 R 2:8, 13, 14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80160, 'spa', 'Gloria, majestad, esplendor — sentido abstracto de gloria, majestad o magnificen', 'Gloria, majestad, esplendor — sentido abstracto de gloria, majestad o magnificencia, extensión de la apariencia imponente de la vestidura física. Ezequiel 17:8 describe una vid plantada en buen suelo que produce ramas de ''esplendor'', y Zacarías 11:3 habla de la ''gloria'' de los pastores arruinada — posiblemente aún jugando con la imagen de la capa del pastor, pero comunicando grandeza perdida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80167, 'spa', 'amar (verbo activo Qal)', 'El sentido verbal Qal básico: amar activamente —apego emocional, devoción y afecto dirigido hacia personas, Dios o cosas. Con 129 ocurrencias es el núcleo del verbo: Jacob amó a Raquel (Gn 29:18), ''amarás a tu prójimo como a ti mismo'' (Lv 19:18). El árabe ahabba y el francés aimer cubren la misma acción verbal fundamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80168, 'spa', 'amante, amigo (participio Qal)', 'El participio activo Qal usado como sustantivo: un amante, amigo, aliado o devoto. Cincuenta y una ocurrencias, incluyendo ''los que me aman'' en la promesa del Decálogo (Ex 20:6) y ''el que ama la sabiduría'' (Pr 29:3). El árabe muḥibb (''el que ama'') confirma el sustantivo agentivo, produciendo con sufijos ''mis amigos/aliados.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80172, 'spa', 'amante ilícito (participio Piel)', 'El participio intensivo Piel: amante ilícito o cómplice adúltero, concentrado en la metáfora matrimonial profética. Diecisiete ocurrencias en Oseas, Jeremías, Ezequiel y Lamentaciones (1:2, 19), donde las alianzas idolátricas de Israel se representan como adulterio. El árabe عُشَّاق (''amantes apasionados/ilícitos'') los distingue de los ''amigos'' legítimos del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80182, 'spa', 'amado/a (participio pasivo)', 'El participio pasivo: el amado, la amada —la persona que es objeto de amor. Nueve ocurrencias, incluyendo la distinción entre ''la esposa amada'' y ''la esposa no amada'' (Dt 21:15-16) y la elegía de Saúl y Jonatán como ''amados y agradables'' (2 S 1:23). El árabe maḥbūb y el alemán Geliebte confirman la semántica pasivo-resultativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80233, 'spa', 'amor (sustantivo abstracto)', 'El sustantivo abstracto אַהֲבָה: el estado o la cualidad del amor en sí mismo. Cuatro ocurrencias donde el sustantivo funciona de manera independiente: los años de Jacob ''le parecieron pocos días por el amor que le tenía'' (Gn 29:20), ''tiempo de amar y tiempo de aborrecer'' (Ec 3:8). El árabe maḥabba y el alemán Liebe confirman la nominalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80278, 'spa', 'pasaje difícil (Os 4:18)', 'Una ocurrencia singular problemática en Os 4:18, donde el texto lee ''aman —¡dad!'' o ''sus gobernantes aman profundamente la vergüenza.'' La evidencia multilingüe diverge, lo que sugiere corrupción textual o una construcción elíptica inusual. La asignación al dominio económico refleja un énfasis en el soborno o el tributo más que en la emoción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80284, 'spa', 'La emoción o disposición abstracta del amor, que abarca la fidelidad al pacto (D', 'La emoción o disposición abstracta del amor, que abarca la fidelidad al pacto (Deuteronomio 7:8), la amistad profunda (1 Samuel 20:17; 2 Samuel 1:26, ''tu amor fue más maravilloso que el amor de mujer''), el deseo romántico (Cantares 2:4-5; 8:6-7) y el afecto humano cotidiano (Proverbios 10:12, ''el amor cubre todas las faltas''). Las traducciones en distintas lenguas convergen en un único término central (amor, amour, Liebe), confirmando un solo campo semántico unificado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80288, 'spa', 'El uso como infinitivo verbal que expresa el acto de amar, frecuentemente regido', 'El uso como infinitivo verbal que expresa el acto de amar, frecuentemente regido por preposiciones que indican propósito o causa: ''por su amor'' (2 Crónicas 2:11; 9:8), ''para amar'' como infinitivo de propósito (1 Reyes 10:9; Oseas 3:1). En Oseas 3:1 Dios ordena al profeta amar a una mujer adúltera, y el infinitivo subraya la acción deliberada de amar más que el sentimiento abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80308, 'spa', '!Ay! — interjeccion que expresa angustia aguda, consternacion o suplica atorment', '!Ay! — interjeccion que expresa angustia aguda, consternacion o suplica atormentada a Dios. Aparece como grito espontáneo de conmoción (Jue 11:35; 2 R 6:5, 15) y en la formula litúrgica אֲהָהּ אֲדֹנָי יְהוִה (''!ay, Señor DIOS!''), presente en Josué, Jueces, Jeremías y Ezequiel. Joel la intensifica con אֲהָהּ לַיּוֹם, ''!ay de aquel día!'' (1:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80310, 'spa', 'Lugar de reunión', 'Las traducciones conservan el topónimo: «Ahava» en español, inglés y otros idiomas. Esdras 8:15 identifica el río Ahava como el punto de encuentro donde Esdras congregó a los exiliados que retornaban. Esdras 8:21 describe el ayuno proclamado en Ahava para buscar la guía y protección divinas. Esdras 8:31 marca la partida desde Ahava hacia Jerusalén, un viaje que requería la mano protectora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80311, 'spa', 'Ehud (nombre propio)', 'El nombre propio Ehud (אֵהוּד), referido principalmente al benjaminita hijo de Gera que sirvió como segundo juez mayor de Israel (Jue 3:15-26). Su zurdera —notable para un benjaminita (''hijo de la mano derecha'')— le permitió ocultar un arma de forma encubierta. Las traducciones preservan el nombre fonéticamente. El segundo portador en 1 Crónicas 7:10 puede representar la misma línea ancestral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80314, 'spa', 'Interrogación retórica', 'El sentido interrogativo «¿dónde?» cumple una función retórica de desafío profético. En Oseas 13:10 Dios pregunta «¿dónde está tu rey?» tras el rechazo de Israel. En el versículo 14, el doble uso — «¿dónde están tus plagas, oh muerte? ¿dónde tu destrucción, oh sepulcro?» — puede leerse como invocación del juicio o como burla ante un poder ya vencido. La Septuaginta con ποῦ (dónde) estableció la lectura que Pablo retomó triunfalmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80316, 'spa', 'Acampar nómada', 'Las traducciones reflejan la acción de plantar tiendas o acampar: «acampaba, acampará» en español, «pitched-tent» en inglés, «dressa-tente» en francés, «zeltete» en alemán. Génesis 13:12 y 13:18 describen los desplazamientos nómadas de Abraham y Lot, donde plantar tiendas marcaba reubicaciones significativas. Isaías 13:20 emplea la ausencia de tiendas como signo de desolación absoluta: ni siquiera los nómadas acamparán allí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80317, 'spa', 'tienda, morada portátil', 'Un refugio portátil de tela, pieles o cortinas que sirve como vivienda. Abarca tiendas nómadas (Gn 4:20; 25:27), campamentos militares, el Tabernáculo (Ex 28:43; 29:4) y usos metafóricos para el hogar o la vida. Las lenguas son notablemente uniformes: árabe خيمة, francés tente, alemán Zelt, todas apuntando a un referente concreto único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80382, 'spa', 'utensilios (texto disputado)', 'Una única ocurrencia problemática en 1 R 7:45, donde el texto refiere a utensilios del templo y algunas versiones leen ''estos vasos.'' Las glosas multilingües se fragmentan aquí —el español da ''utensilios''— lo que sugiere una dificultad textual o de análisis morfológico más que un sentido genuino de ohel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80396, 'spa', 'Nombre alegórico samaritano', 'El nombre propio alegórico אָהֳלָה, que significa ''su tienda'' o ''la de la tienda'', usado por Ezequiel para personificar a Samaria como la mayor de dos hermanas adúlteras (Ezeq 23:4, 5, 36, 44). El nombre implica culto ilegítimo en santuarios autoedificados, en contraste con el tabernáculo de Jerusalén. Su ''adulterio'' con Asiria (Ezeq 23:5-10) representa las alianzas políticas y religiosas del reino del norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80397, 'spa', 'Artesano del tabernáculo', 'El nombre propio אָהֳלִיאָב, que designa al hijo de Ahisamac de la tribu de Dan, nombrado por Dios como asistente principal de Bezaleel en la construcción del tabernáculo y su mobiliario (Éx 31:6). Diestro en grabado, bordado y diseño textil (Éx 38:23), representa la tradición del artesano divinamente dotado. Su nombre — ''tienda del padre'' — resuena con su función como constructor de la morada de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80398, 'spa', 'Oholiba (nombre simbólico)', 'Oholiba (אָהֳלִיבָה, ''mi tienda está en ella''), nombre simbólico de Jerusalén en Ezequiel 23. Es retratada como la hermana menor de Oholá (Samaria), ambas representadas como esposas adúlteras de Yahvé. El nombre implica que Dios estableció su tienda-santuario dentro de Jerusalén, pero ella persiguió alianzas extranjeras e idolatrías aún más descaradamente que su hermana (Ezek 23:11). Las seis apariciones se encuentran en este único capítulo alegórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80400, 'spa', 'Oholibama (nombre propio)', 'Nombre personal y de clan Oholibama (אָהֳלִיבָמָה), etimológicamente ''tienda del lugar alto'', que designa a la esposa de Esaú (hija de Aná, nieta de Zibeón el heveo) y al clan edomita que desciende de ella. Sus ocho apariciones se concentran en Génesis 36 y 1 Crónicas 1:52, los registros genealógicos edomitas. Las traducciones en todos los idiomas transliteran el nombre de manera uniforme con variaciones mínimas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80403, 'spa', 'Áloes aromáticos', 'Árboles de áloe o áloes como materia aromática fragante. Todas las traducciones convergen en un solo sentido: español ''áloes'', francés ''aloès'', alemán ''Aloe''. En Números 24:6 el plural designa árboles aromáticos (en paralelo con cedros), mientras que en Salmos 45:8, Proverbios 7:17 y Cantares 4:14 se refiere al costoso perfume extraído de dicha madera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80404, 'spa', 'Aarón (nombre propio)', 'Nombre propio masculino de etimología incierta, portado por el hermano mayor de Moisés (Ex 7:7), primer sumo sacerdote de Israel. Fue vocero ante el Faraón (Ex 4:14-16), consagrado en la ceremonia de ordenación (Lv 8) y fundador de la línea sacerdotal hereditaria (''hijos de Aarón,'' Lv 1:5; Nm 3:3). La narrativa registra también sus fracasos, como el becerro de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80414, 'spa', 'o (conjunción disyuntiva)', 'Conjunción disyuntiva que presenta dos o más alternativas, equivalente al español ''o.'' En contextos legislativos (Levítico, Éxodo) introduce un caso particular bajo un estatuto más amplio: ''o si acorneare a un hijo'' (Ex 21:31). Ocasionalmente conlleva el matiz de ''o más bien,'' sugiriendo preferencia entre opciones (Gn 24:55). La uniformidad interlingüística confirma su función gramatical básica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80417, 'spa', 'Médium o espíritu nigromante', 'Médium o espíritu nigromante. Persona que conjura o canaliza los espíritus de los muertos, o el espíritu mismo invocado mediante la adivinación. Aparece consistentemente emparejado con yiddeoni en prohibiciones legales (Lv 19:31; 20:6, 27; Dt 18:11) y en contextos narrativos (1 Sam 28:3, 7-9; 2 R 21:6; 23:24). Las traducciones lo vierten como ''médium'' o ''espíritu familiar'', enfatizando la entidad fantasmal o la persona que la invoca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80424, 'spa', 'Odre o recipiente de cuero', 'Odre o recipiente de cuero. Recipiente de cuero u odre para vino, atestiguado solo en Job 32:19, donde Elihú compara la presión de las palabras no expresadas con vino nuevo a punto de reventar odres frescos. Este sentido concreto y cotidiano comparte un vínculo etimológico con la forma hueca e hinchada que también sugería la ''voz hueca'' del nigromante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80428, 'spa', 'Río Ulai', 'Las traducciones conservan el nombre del río: en español «el río», «río». Daniel 8:2 sitúa la visión junto al Ulai en Susa, la capital administrativa persa. Daniel 8:3 describe al carnero de dos cuernos junto al río. Daniel 8:6 narra al macho cabrío embistiendo al carnero junto al río. La identificación precisa del Ulai sigue siendo debatida entre los eruditos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80429, 'spa', 'Tizón ardiente', 'Las traducciones coinciden en «tizón» o «tizones». Isaías 7:4 describe a los enemigos de Israel como «tizones humeantes», amenazantes en apariencia pero casi extintos. Amós 4:11 presenta a Israel como «un tizón arrebatado del fuego», apenas rescatado de la destrucción total. Zacarías 3:2 aplica la misma imagen a Josué, el sumo sacerdote, restaurado tras el exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80430, 'spa', 'Causa, razón u ocasión, siempre en el plural constructo con עַל para formar ''a c', 'Causa, razón u ocasión, siempre en el plural constructo con עַל para formar ''a causa de'' o ''por motivo de''. Introduce la razón motivante detrás de una acción o emoción: la angustia de Abraham por Ismael (Gn 21:11), su confrontación por el pozo (Gn 21:25), Jetro al oír lo que Dios hizo por Israel (Ex 18:8) y la oposición a Moisés por causa de la esposa cusita (Nm 12:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80439, 'spa', 'Deseo neutral o positivo, predominantemente en la conjugación Piel', 'Deseo neutral o positivo, predominantemente en la conjugación Piel: desear comida (Dt 12:20; 14:26), la autoridad de un rey (2 Sam 3:21; 1 Re 11:37) o Dios deseando a Sion (Sal 132:13). El término español ''desear'' corresponde a este registro moderado. El nephesh (alma/apetito) del sujeto generalmente rige el verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80440, 'spa', 'Anhelo intenso con connotaciones morales negativas, característico del Hitpael e', 'Anhelo intenso con connotaciones morales negativas, característico del Hitpael en contextos de prohibición. El antojo de carne de la turba en Kibrot-hataavá (Nm 11:4, 34) y el ''no codiciarás'' del Décimo Mandamiento (Dt 5:21) anclan este sentido. Proverbios 21:26 advierte que el perezoso codicia todo el día. El español ''codiciar'' refleja el peso moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80445, 'spa', 'Anhelo emocional profundo o nostalgia, también en Hitpael pero sin juicio negati', 'Anhelo emocional profundo o nostalgia, también en Hitpael pero sin juicio negativo. Los soldados de David arriesgaron sus vidas porque él anheló agua de la cisterna de Belén (2 Sam 23:15; 1 Cr 11:17). El salmo real invita al rey a ''desear'' la belleza de la novia (Sal 45:11). Las traducciones preservan la calidez afectiva que distingue este sentido tanto del deseo neutro como de la codicia pecaminosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80461, 'spa', 'Deseo, anhelo, apetencia', 'Deseo, anhelo o apetencia: un querer intenso e interior que suele aparecer en la construcción ''deseo del alma'' (ʾavvat nepeš). Abarca el apetito físico moralmente neutro por alimento (Dt 12:15, 20, 21), el anhelo de un levita por servir en el santuario central (Dt 18:6), la voluntad decidida de un rey (1 S 23:20) y el propósito divino (Os 10:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80465, 'spa', 'Persona y región', 'Las traducciones conservan el nombre: en español «Uzal», «de Uzal». Génesis 10:27 y 1 Crónicas 1:21 enumeran a Uzal entre los hijos de Joctán, trazando la genealogía árabe desde Sem. Ezequiel 27:19 (según enmienda «de Uzal») identifica la región como fuente de bienes comerciales para Tiro: hierro, casia y cálamo del sur de Arabia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80466, 'spa', 'Interjección apasionada que expresa dolor, desesperación o condenación profética', 'Interjección apasionada que expresa dolor, desesperación o condenación profética. Como lamento personal: el grito de indignidad de Isaías ante el trono divino (Is 6:5), la angustia de Jeremías por su vocación (Jer 15:10; 45:3) y el terror colectivo de Israel ante la derrota militar (1 Sam 4:7-8; Jer 4:13, 31; 6:4). Como denuncia profética: oráculos contra Moab (Nm 21:29), la ''ciudad sanguinaria'' (Ez 24:6, 9) y la devastadora advertencia de Oseas (Os 7:13; 9:12). Proverbios lo emplea como sustantivo vinculándolo al exceso de vino (Pr 23:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80471, 'spa', 'Persona caracterizada por una obstinada obtusidad moral y espiritual que rechaza', 'Persona caracterizada por una obstinada obtusidad moral y espiritual que rechaza la sabiduría, la disciplina y el temor del SEÑOR. Proverbios traza un perfil extenso: el necio desprecia la instrucción (Pr 1:7; 15:5), se burla de la culpa (Pr 14:9), provoca contiendas (Pr 20:3) y es incorregible aun bajo la corrección más extrema (Pr 27:22). Los profetas emplean el término como acusación: Oseas llama necio al profeta (Os 9:7), Isaías ridiculiza a los consejeros de Egipto (Is 19:11) y Jeremías acusa a Israel de ser un pueblo ''necio que no me conoce'' (Jer 4:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80483, 'spa', 'Rey de Babilonia', 'Las traducciones conservan el nombre real: en español «Evil-Merodac». 2 Reyes 25:27 registra que en su primer año de reinado, Evil-merodac liberó a Joaquín de la prisión babilónica. Jeremías 52:31 ofrece un relato paralelo, confirmando que Joaquín recibió favor real. Su clemencia hacia el rey cautivo simbolizó esperanza para los exiliados de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80486, 'spa', 'Adverbio de posibilidad contingente que introduce una cláusula cuyo resultado es', 'Adverbio de posibilidad contingente que introduce una cláusula cuyo resultado es incierto pero contemplado con esperanza, temor o especulación. Con mayor frecuencia expresa un deseo esperanzado (''quizás Dios sea misericordioso'', 2 Samuel 16:12; ''quizás sea edificada por medio de ella'', Génesis 16:2) o una duda aprensiva (''quizás la mujer no me siga'', Génesis 24:5, 39). En la intercesión por Sodoma (Génesis 18:24-32), funciona como un condicional virtual, rebajando iterativamente el número de justos necesarios para la salvación de la ciudad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80489, 'spa', 'La sala de entrada cubierta o vestíbulo de un edificio sagrado o real', 'La sala de entrada cubierta o vestíbulo de un edificio sagrado o real: un pórtico que forma la sección frontal del templo o palacio. Concentrado en las descripciones del templo de Salomón (1 Reyes 6:3; 7:19, 21), su complejo palaciego con su ''pórtico de columnas'' y ''pórtico del trono'' (1 Reyes 7:6-7), y el templo visionario de Ezequiel (Ezequiel 40:7-49). Joel 2:17 invoca el espacio ''entre el pórtico y el altar'' como lugar de intensa intercesión sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80505, 'spa', 'Nombre propio personal', 'Ulam: nombre personal que aparece en dos contextos genealógicos distintos. El español y el inglés transliteran uniformemente ''Ulam'', mientras que el francés usa ''Oulam''. En 1 Crónicas 7:16-17 Ulam pertenece a la tribu de Manasés; en 1 Crónicas 8:39-40 el nombre designa un clan guerrero benjaminita descendiente de Saúl.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80506, 'spa', 'Pero en verdad / y ciertamente (conjunción adversativo-aseverativa)', 'Pero en verdad / y ciertamente (conjunción adversativo-aseverativa). Conjunción adversativo-aseverativa que señala un fuerte ''pero'' o contraste enfático, a menudo combinada con waw como וְאוּלָם. En Gn 48:19 Jacob concede la grandeza de Manasés pero insiste en que Efraín lo superará. En Éx 9:16 subraya el propósito soberano de Dios tras la existencia de Faraón. A lo largo de Job (2:5; 5:8; 13:3) introduce la contrarréplica desafiante del hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80515, 'spa', 'Insensatez moral e intelectual, la cualidad definitoria del kesil y el ewil en P', 'Insensatez moral e intelectual, la cualidad definitoria del kesil y el ewil en Proverbios y Salmos. Contrastada explícitamente con el entendimiento (tevunah, Pr 14:29; 15:21), no describe simple ignorancia sino un rechazo deliberado de la sabiduría. Proverbios 22:15 declara que está ''ligada al corazón del muchacho,'' removible solo mediante la disciplina. El salmista confiesa que su necedad no está oculta ante Dios (Sal 38:5; 69:5), vinculándola a la culpa y la exposición espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80522, 'spa', 'Jefe edomita', 'Las traducciones conservan el nombre propio: en español «Omar». Génesis 36:11 enumera a Omar entre los hijos de Elifaz, primogénito de Esaú. Génesis 36:15 lo identifica como jefe entre los descendientes de Esaú en Edom. 1 Crónicas 1:36 repite la genealogía, confirmando el lugar de Omar en la estructura tribal edomita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80523, 'spa', 'Vigor, fuerza, poder viril — vigor físico, fuerza varonil, vitalidad reproductiv', 'Vigor, fuerza, poder viril — vigor físico, fuerza varonil, vitalidad reproductiva. El significado central aparece en la bendición de Jacob a Rubén: ''el principio de mi vigor'' (Gn 49:3), refiriéndose al primogénito como prueba de poder procreador. Deuteronomio 21:17 hace eco de esto en la ley de herencia. En Job, la palabra describe la fuerza humana que desfallece (Job 18:7, 12) y el poder muscular bruto de Behemot (Job 40:16). Isaías la aplica al poder cósmico de Dios (Is 40:26, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80526, 'spa', 'Riqueza, sustancia, bienes — riqueza material, sustancia o bienes, extensión del', 'Riqueza, sustancia, bienes — riqueza material, sustancia o bienes, extensión del poder físico a los recursos que ese poder produce. En Job 20:10 los hijos del malvado deben ''restituir su riqueza'', donde las posesiones representan el fruto de la energía vital. Oseas 12:8 confirma este sentido: Efraín dice ''he hallado riqueza para mí'', alardeando de prosperidad material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80533, 'spa', 'Ciudad egipcia On', 'Las traducciones conservan el nombre de la ciudad: «On» en español, inglés, francés y alemán. Génesis 41:45, 50 y 46:20 vinculan el matrimonio de José con Asenat, hija del sacerdote de On, integrándolo en la élite egipcia. Ezequiel 30:17 pronuncia juicio sobre On (allí llamada «Avén», un juego de palabras con maldad), prediciendo que sus jóvenes caerán a espada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80534, 'spa', 'iniquidad, maldad', 'Iniquidad, maldad, perversión — el sentido dominante con 69 apariciones, abarcando el mal moral activo, la condición pecaminosa y la culpa que se adhiere al malhechor. La expresión פֹּעֲלֵי אָוֶן (''obradores de iniquidad'') es casi formulaica en los Salmos (Sal 5:5; 6:8; 14:4; 36:12; 53:4; 59:2; 92:7; 94:4; 125:5; 141:9), estigmatizando a los transgresores persistentes como una clase.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80543, 'spa', 'aflicción, calamidad', 'Aflicción, calamidad, pesar — 3 apariciones donde el énfasis recae en las consecuencias dañinas de la maldad, más que en el acto moral. En Sal 90:10 la vida humana es ''trabajo y aflicción,'' un merismo para las penas de la existencia. Jer 4:15 anuncia אָוֶן desde Efraín, y Hab 3:7 contempla las tiendas de Cusán ''en aflicción.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80545, 'spa', 'duelo, lamento', 'Duelo, lamento — 2 apariciones en contextos rituales. En Gn 35:18 Raquel nombra a su hijo moribundo Ben-oní (''hijo de mi dolor''), y en Dt 26:14 y Os 9:4 el término aparece en conexión con ritos fúnebres y el pan de los enlutados. En Oseas, el pan asociado con אָוֶן queda ritualmente contaminado, vinculando duelo e impureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80547, 'spa', 'Avén (topónimo)', 'Avén como topónimo — 1 aparición clara en Os 10:8, donde ''los altos de Avén'' designa el santuario idolátrico, probablemente una denominación despectiva de Bet-el. La palabra funciona simultáneamente como nombre propio y juicio teológico: el lugar recibe el nombre de lo que verdaderamente es. Sigue el patrón profético de renombramiento polémico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80549, 'spa', 'vacuidad, vanidad', 'Vacuidad, vanidad, nada — 3 apariciones donde אָוֶן describe lo fundamentalmente desprovisto de sustancia o realidad. Isaías 41:29 declara que los ídolos son אָוֶן (''nada''); Amós 5:5 juega con que Bet-el se convertirá en אָוֶן (''nada''); Zacarías 10:2 dice que los terafines hablan אָוֶן (''vacuidad''). Aquí la palabra se aproxima a הֶבֶל en significado — futilidad e insustancialidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80551, 'spa', 'malvados, poderosos', 'Uso sustantivado: malvados o poderosos — 1 aparición en Pr 11:7, donde ''la esperanza de אָוֶן perece'' aparentemente emplea el término como sustantivo referido a personas caracterizadas por la maldad o el poder opresor. La traducción española ''fuertes'' sugiere una lectura alternativa vinculada al hebreo אוֹן (''vigor, riqueza''), y de hecho algunos lexicógrafos tratan este caso como un homónimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80559, 'spa', 'Ciudad benjaminita', 'El topónimo אוֹנוֹ, que designa una ciudad benjaminita y su llanura circundante, al noroeste de Lida en la región de la Sefelá. Mencionada primero como fundada por Semed el benjaminita (1 Cr 8:12), aparece de forma prominente en registros postexílicos: el censo de los exiliados que regresaron (Esd 2:33; Neh 7:37), la lista de repoblación (Neh 11:35) y la negativa de Nehemías a reunirse con sus enemigos en su valle (Neh 6:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80560, 'spa', 'Nombre personal', 'Onam — nombre personal derivado de una raíz que sugiere vigor o fuerza. Sus cuatro apariciones corresponden a individuos nombrados en listas genealógicas. El Onam horita (Gn 36:23; 1 Cr 1:40) pertenece a los clanes preeisraelitas de Edom, mientras que el Onam judahita (1 Cr 2:26, 28) aparece en la línea jerameelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80561, 'spa', 'Onán (hijo de Judá)', 'El nombre propio masculino Onán (אוֹנָן, ''vigoroso''), referido al segundo hijo de Judá con su esposa cananea (Gn 38:4). Es recordado por su negativa a engendrar descendencia para su hermano Er, lo que provocó el juicio divino (Gn 38:8-10). Las listas genealógicas posteriores en Génesis 46:12, Números 26:19 y 1 Crónicas 2:3 registran su nombre en los censos tribales de Judá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80565, 'spa', 'Ofir (topónimo, tierra del oro) — Nombre propio que designa (a) un hijo de Joctá', 'Ofir (topónimo, tierra del oro) — Nombre propio que designa (a) un hijo de Joctán en la Tabla de las Naciones (Gn 10:29; 1 Cr 1:23) y (b) el célebre territorio ultramarino del que los barcos de Salomón traían oro, piedras preciosas y madera de sándalo (1 R 9:28; 10:11; 2 Cr 8:18; 9:10). En textos poéticos y proféticos, ''oro de Ofir'' funciona como superlativo del oro más fino (Sal 45:9; Job 22:24; 28:16; Is 13:12). Las 13 ocurrencias tratan el nombre uniformemente como sustantivo propio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80569, 'spa', 'Rueda o disco giratorio que designa un componente mecánico funcional en varios c', 'Rueda o disco giratorio que designa un componente mecánico funcional en varios contextos: ruedas de carros quitadas en el juicio divino junto al mar (Éxodo 14:25) o retumbando en batalla (Nahúm 3:2); las ornamentadas ruedas de bronce de las bases de las fuentes del templo de Salomón con ejes, aros y rayos (1 Reyes 7:30-33); la rueda del trillo como instrumento de aventamiento o castigo (Isaías 28:27; Proverbios 20:26); y, sobre todo, las ruedas vivientes cubiertas de ojos en la visión del trono de Ezequiel (Ezequiel 1:15-21; 10:6-19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80583, 'spa', 'Apresurarse, presionar, urgir — Apresurarse, darse prisa, presionar o urgir, ya ', 'Apresurarse, presionar, urgir — Apresurarse, darse prisa, presionar o urgir, ya sea intransitivamente (ser precipitado, correr) en el Qal o causativamente (presionar, urgir a alguien) en el Hif''il. Los ángeles apremian a Lot al amanecer (Gn 19:15), los capataces presionan a los israelitas (Éx 5:13), el sol no se apresura a ponerse durante la batalla de Josué (Jos 10:13), y Proverbios advierte repetidamente contra la prisa en el hablar y el actuar (19:2; 21:5; 28:20; 29:20). El árabe muta''ajjil y las traducciones existentes como ''apremiaban'' y ''se apresuró'' confirman este campo semántico de urgencia y precipitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80590, 'spa', 'Ser estrecho, estar constreñido — Ser estrecho, angosto o constreñido en el espa', 'Ser estrecho, estar constreñido — Ser estrecho, angosto o constreñido en el espacio. En Josué 17:15, las tribus de José se quejan de que la región montañosa de Efraín «es demasiado estrecha» para su creciente población: un significado espacial, no temporal. El árabe daqa (''ser estrecho'') y el español ''estrecho'' respaldan este sentido distinto de constricción física, semánticamente muy alejado de la urgencia y la prisa del significado principal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80591, 'spa', 'tesoro, bienes valiosos', 'Riqueza almacenada o posesiones valiosas consideradas como propiedad. A diferencia del sentido 1, el foco está en el contenido, no en el contenedor. Cuando se llevan ''los tesoros de la casa del SEÑOR'' (1 R 14:26), la palabra denota los objetos de oro y plata. Jeremías 15:13 habla de tesoros entregados como botín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80592, 'spa', 'tesorería del templo', 'Sala o bóveda dedicada al resguardo de objetos de valor — en particular la tesorería real o del templo. En Jos 6:19 los metales capturados van a la ''tesorería del SEÑOR,'' y 1 R 7:51 describe a Salomón depositando objetos sagrados en las tesorerías del templo. Refuerza el sentido arquitectónico del recinto como lugar consagrado de custodia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80595, 'spa', 'almacén, granero', 'Almacén o granero para provisiones o elementos cósmicos. Joel 1:17 menciona graneros en ruinas durante hambruna. Job 38:22 pregunta ''¿Has entrado en los depósitos de la nieve?'' y Sal 135:7 dice que Dios saca el viento de sus depósitos — metáfora que trata el clima como inventario divino. Dt 32:34 describe los juicios de Dios ''sellados en mi almacén.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80632, 'spa', 'Hifil causativo', 'Hifil causativo: dar luz, iluminar, hacer brillar — el sentido dominante con 23 ocurrencias, abarcando creación, tabernáculo y teofanía. En Génesis 1:15 y 1:17 las lumbreras son puestas en el firmamento ''para alumbrar sobre la tierra''; en Éxodo 25:37 las lámparas se disponen ''para alumbrar al frente del'' candelabro; en Éxodo 13:21 la columna de fuego alumbra de noche. El español ''alumbrar'' e ''iluminar'' reflejan este sentido causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80633, 'spa', 'Hifil en la fórmula de la bendición sacerdotal', 'Hifil en la fórmula de la bendición sacerdotal: hacer resplandecer el rostro sobre alguien, expresando favor divino y gracia. Ocho ocurrencias concentradas en los Salmos (13:3; 31:16; 67:1; 80:3, 7, 19; 119:135) y ancladas en la bendición aarónica de Números 6:25 (''haga resplandecer YHWH su rostro sobre ti''). El español ''haz resplandecer tu rostro'' captura fielmente esta expresión litúrgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80635, 'spa', 'Nifal pasivo/reflexivo', 'Nifal pasivo/reflexivo: ser iluminado, resplandecer, amanecer — tres ocurrencias en contextos poéticos elevados. En 2 Samuel 2:32 ''amaneció'' cuando los hombres de Joab llegaron a Hebrón; en Job 33:30 Dios actúa ''para ser iluminado con la luz de la vida''; en Salmo 76:4 Dios es ''resplandeciente'' desde los montes de presa. El español ''resplandeciente'' refleja esta voz pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80636, 'spa', 'Hifil con el sentido específico de encender o prender fuego o lámpara — 3 ocurre', 'Hifil con el sentido específico de encender o prender fuego o lámpara — 3 ocurrencias donde el énfasis recae en la ignición física más que en la iluminación celeste o metafórica. En Salmo 18:28 ''tú enciendes mi lámpara''; en Isaías 27:11 mujeres vienen ''encendiéndola''; y en Malaquías 1:10 Dios dice ''no encenderéis fuego en mi altar en vano''. El español ''encender'' marca claramente la acción de prender fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80643, 'spa', 'Qal intransitivo', 'Qal intransitivo: brillar, hacerse luz, resplandecer — el sentido estativo/incoativo básico con 6 ocurrencias. En Génesis 44:3 ''la mañana se hizo luz''; en 1 Samuel 14:27 los ojos de Jonatán ''se iluminaron'' al probar la miel; en Proverbios 4:18 la senda de los justos ''resplandece más y más''. El español ''resplandecer'' y ''brillar'' seleccionan el vocabulario de luminosidad intransitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80668, 'spa', 'luz (general y metafórica)', 'La luz en toda su gama física y metafórica: el sentido primario abrumador con 116 ocurrencias, que abarca creación, literatura sapiencial, visión profética y salmos. En Gn 1:3 Dios crea la luz como primer acto de ordenar el caos; en Job 3:20 ''luz'' significa vida; en Sal 27:1 ''YHWH es mi luz'' expresa salvación y protección divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80681, 'spa', 'relámpago, fulgor', 'Relámpago o destello súbito: 3 ocurrencias en la poesía teofánica de Job. En Job 36:30 Dios ''extiende su relámpago (אוֹרוֹ) a su alrededor''; en Job 37:3 ''lo lanza bajo todo el cielo, y su relámpago hasta los confines de la tierra''; en Job 37:11 la nube ''esparce su relámpago.'' El contexto de tormenta lo distingue de la luz estable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80695, 'spa', 'lumbreras (astros)', 'Las grandes lumbreras: una única ocurrencia en Sal 136:7, ''Al que hizo grandes lumbreras (אוֹרִים גְּדֹלִים),'' refiriéndose al sol y la luna descritos en los versículos siguientes (136:8-9). El español ''lumbreras'' y el francés ''lumières'' emplean un término especializado para los portadores celestiales de luz, distinguiéndolos de la luz como fenómeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80697, 'spa', 'alba (referencia temporal)', 'Luz del alba en un contexto temporal-administrativo: una única ocurrencia en Neh 8:3, donde Esdras lee la Torá públicamente ''desde la luz (מִן־הָאוֹר) hasta el mediodía,'' es decir, desde el amanecer hasta el mediodía. La expresión מִן־הָאוֹר עַד־מַחֲצִית הַיּוֹם delimita un bloque horario de lectura pública matutina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80704, 'spa', 'Fuego como llama luminosa', 'Fuego concebido como llama visible y luz radiante. Isaías lo emplea para el fuego autoencendido de los malvados (Is 50:11), el fuego que calienta y cuya luz se disfruta (Is 44:16) y el fuego consumidor del juicio (Is 47:14). En Is 31:9 y Ez 5:2 denota fuego literal en contextos de catástrofe nacional. Las traducciones españolas ''fuego'' y ''luz de'' captan conjuntamente la doble cualidad de llama y resplandor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80707, 'spa', 'Ciudad de Abraham', 'Ur de los caldeos — la antigua ciudad sumeria de la que emigró la familia de Abraham. Todas las traducciones la tratan como topónimo con contexto preposicional: «de Ur de los caldeos», «en Ur». Las cuatro apariciones bíblicas sitúan a Ur como punto de partida de la vocación patriarcal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80708, 'spa', 'Luz, resplandor', 'Las traducciones muestran variación: español «luz, luces, como la luz», francés «lumière», alemán «Licht». Ester 8:16 empareja la luz con la alegría cuando los judíos celebran la reversión del complot de Amán. Salmo 139:12 usa luz y tinieblas para expresar que nada se oculta de Dios. Isaías 26:19 emplea «rocío de luces» como imagen enigmática de vida resucitada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80711, 'spa', 'Uri (nombre propio)', 'El nombre propio masculino Uri (אוּרִי, ''ardiente'', o contracción de Urías), aplicado a tres individuos distintos: (a) un príncipe de Judá, padre de Bezaleel, el artesano del tabernáculo (Éx 31:2; 1 Cr 2:20; 2 Cr 1:5); (b) un portero que se había casado con una mujer extranjera (Esd 10:24); y (c) el padre de Geber, uno de los oficiales regionales de Salomón (1 R 4:19). Las ocho apariciones se transliteran uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80713, 'spa', 'Nombre teofórico', 'Uriel — nombre personal teofórico que significa «llama de Dios» o «Dios es mi luz». El Uriel coatita (1 Cr 6:24; 15:5, 11) tuvo la sagrada responsabilidad de transportar el arca, mientras que el Uriel de 2 Crónicas 13:2 vincula la casa real davídica con el linaje levítico mediante matrimonio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80714, 'spa', 'El nombre propio teofórico Urías/Uriyahu, portado por al menos tres figuras bíbl', 'El nombre propio teofórico Urías/Uriyahu, portado por al menos tres figuras bíblicas: Urías el hitita, el oficial de David asesinado (2 Samuel 11:3-26; 23:39); Urías el sacerdote bajo Acaz (2 Reyes 16:10-16; Isaías 8:2); y un Urías postexílico (Esdras 8:33; Nehemías 3:4). A pesar de tener múltiples referentes, el nombre constituye una única entrada léxica. Las traducciones lo transliteran consistentemente: ''Urías'' en español, ''Urie'' en francés, ''Uria'' en alemán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80720, 'spa', 'Urim (objeto oracular)', 'Los Urim: objetos sagrados de sorteo alojados en el pectoral del sumo sacerdote para obtener oráculos divinos. Siempre emparejados con los Tumim, se colocaban en el pectoral de juicio (Éx 28:30; Lv 8:8) y servían para decisiones críticas en nombre de la comunidad. Moisés ordena que Josué consulte ''por el juicio de los Urim'' ante Eleazar (Nm 27:21). Para la época de Saúl ya habían dejado de dar respuesta (1 S 28:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80724, 'spa', 'Consentir, aceptar', 'Consentir o aceptar términos o condiciones (solo en Nifal). Las cuatro apariciones involucran negociación formal: tres en las negociaciones matrimoniales de Siquem (Gn 34:15, 22, 23) y una en el acuerdo sobre los ingresos del templo (2 R 12:8). Expresa siempre un asentimiento deliberado y voluntario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80725, 'spa', 'senal, senal milagrosa', 'senal, senal milagrosa. Senal visible, portento o acto milagroso que sirve como evidencia del poder divino o de la autenticidad profetica. Este es el sentido dominante, abarcando desde las plagas de Egipto (Ex 4:8-9) hasta las confirmaciones profeticas (1 Sam 10:7) y la senal prometida a Acaz (Isa 7:14). En las principales traducciones europeas -- espanol ''senal'', frances ''signe'', aleman ''Zeichen'' -- aparece la misma palabra nuclear.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80733, 'spa', 'marca, senal de pacto', 'marca, senal de pacto. Prenda, emblema o marca distintiva que conmemora un pacto o acuerdo entre Dios y su pueblo. El arco iris tras el diluvio (Gen 9:12-17), el rito de la circuncision (Gen 17:11) y la sangre del cordero pascual (Ex 12:13) reciben este nombre. El frances ''signe de'' y el aleman ''zum Zeichen'' emplean construcciones preposicionales que resaltan la funcion relacional y conmemorativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80743, 'spa', 'estandarte, ensena', 'estandarte, ensena. Estandarte militar o tribal, ensena o bandera usada para identificacion y reunion de tropas. Este sentido infrecuente aparece en Sal 74:4, donde los enemigos colocan sus ''senales'' (estandartes) en el recinto del templo, y posiblemente en Job 21:29 refiriendose a marcas de viajeros. La evidencia multilingue muestra incertidumbre, lo que sugiere que los traductores reconocen un campo semantico distinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80749, 'spa', 'entonces', 'Adverbio temporal que apunta a un momento definido en el pasado o el futuro, marcando el inicio dramático de una acción. Con referencia pasada narra un comienzo: ''entonces cantó Moisés este cántico'' (Ex 15:1); ''entonces comenzaron a invocar el nombre de YHWH'' (Gn 4:26). Con referencia futura introduce transformación profética: ''entonces los ojos de los ciegos serán abiertos'' (Is 35:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80751, 'spa', 'Desde antiguo, hace mucho tiempo', 'Desde antiguo, hace mucho tiempo. Uso adverbial que apunta a un pasado antiguo indefinido: ''desde antiguo, desde hace mucho''. Se emplea en el lenguaje poético y profético elevado para evocar permanencia o antigüedad: el trono de Dios está establecido מֵאָז (Sal 93:2), la Sabiduría fue engendrada מֵאָז (Pr 8:22). Isaías 44:8 y 45:21 lo usan para referirse a las revelaciones de Dios desde mucho tiempo atrás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80752, 'spa', 'Desde que, a partir del momento en que', 'Desde que, a partir del momento en que. Uso conjuncional-preposicional que significa ''desde que, a partir del momento en que'', introduciendo una cláusula que especifica un momento pasado definido. En Génesis 39:5, el Señor bendijo la casa de Potifar מֵאָז, ''desde que'' José tomó el cargo. Éxodo 4:10 tiene a Moisés diciendo ''desde que hablaste a tu siervo''. Rut 2:7 emplea la misma construcción para un inicio temporal concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80757, 'spa', 'Calentar, encender', 'Las traducciones reflejan la acción de calentar: español «calentar, ser calentado», francés y alemán conservan formas arameas similares. Daniel 3:19 describe la orden del rey de sobrecalentar el horno siete veces más, expresión de su ira y determinación de destruir a los tres fieles. Daniel 3:22 señala irónicamente que el calor excesivo mató a los verdugos, no a los condenados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80760, 'spa', 'Hisopo (planta) — Pequeña hierba arbustiva (probablemente Origanum syriacum o un', 'Hisopo (planta) — Pequeña hierba arbustiva (probablemente Origanum syriacum o una especie relacionada) utilizada como instrumento de aspersión ritual en las ceremonias de purificación israelitas. Central en tres grandes rituales: la marca con sangre de los dinteles en la Pascua (Éx 12:22), la purificación de enfermedades cutáneas y casas contaminadas (Lv 14:4, 6, 49, 51-52), y el agua de purificación de la vaca roja (Nm 19:6, 18). El clamor penitencial de David «purifícame con hisopo» (Sal 51:9) transforma el instrumento litúrgico en metáfora de limpieza interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80766, 'spa', 'Cinturón, cinto, faja — Prenda o banda que se lleva alrededor de la cintura o lo', 'Cinturón, cinto, faja — Prenda o banda que se lleva alrededor de la cintura o los lomos, hecha de cuero (la vestimenta profética de Elías, 2 R 1:8) o de lino (el cinturón simbólico de Jeremías, Jer 13:1-11). El אֵזוֹר funciona tanto como ropa práctica como poderoso símbolo profético: los cinturones inquebrantables de los guerreros asirios (Is 5:27), el Mesías ceñido de justicia (Is 11:5) y las fajas decorativas de los guerreros caldeos en la visión de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80772, 'spa', 'Entonces, en consecuencia', 'Las traducciones lo rinden uniformemente como «entonces»: español «entonces», francés «alors», alemán «dann». Salmo 124:3, 4 y 5 emplea la palabra tres veces en una poderosa estructura retórica tras «si no fuera por el SEÑOR»: entonces los enemigos los habrían tragado vivos, las aguas los habrían arrastrado, las corrientes los habrían ahogado. El triple uso crea un crescendo de peligro inminente y liberación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80773, 'spa', 'Porción memorial sacrificial', 'La porción memorial de la ofrenda de cereal: el puñado representativo de harina mezclada con aceite y todo el incienso que el sacerdote quema sobre el altar como símbolo de la ofrenda completa (Lv 2:2, 9, 16; 6:15; Nm 5:26). También se aplica al incienso colocado sobre el pan de la proposición como memorial (Lv 24:7) y al cereal sustituto de la ofrenda por el pecado del muy pobre (Lv 5:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80775, 'spa', 'Irse o agotarse', 'Irse, partir o agotarse. Abarca la partida física (Prov 20:14 — el comprador se va por su camino), el vagabundeo inquieto (Jer 2:36 — ''¿por qué andas tanto mudando tu camino?'') y el agotamiento figurado de recursos: el pan ''se acabó de nuestras vasijas'' (1 Sam 9:7), las aguas se evaporan del mar (Job 14:11) y las fuerzas ''se han consumido'' (Deut 32:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80776, 'spa', 'Ir, caminar (Qal)', 'Ir, caminar o viajar a un destino, abarcando tanto el movimiento completado (perfectivo: ''fue'', ''fuimos'', ''fueron'') como el movimiento ordenado (imperativo: ''¡ve!''). Se encuentra en Esd 4:23 y 5:8 para viajes oficiales a Jerusalén, en Esd 5:15 para la orden de Ciro, y en Dn 2:17, 24 para los desplazamientos de Daniel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80781, 'spa', 'prestar oído, escuchar atentamente', 'prestar oído, escuchar atentamente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80801, 'spa', 'oído, órgano auditivo', 'El oído anatómico como órgano de la audición, usado literalmente (la oreja perforada para la servidumbre en Ex 21:6, ungida con sangre en la consagración sacerdotal en Lv 8:23, adornada con pendientes en Gn 35:4) y metonímicamente en la frase בְּאָזְנֵי (''a oídos de'') para indicar audiencia pública o proclamación ante testigos (Gn 23:10, 16; Dt 31:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80859, 'spa', 'Ceñirse a sí mismo (Hitpael)', 'Ceñirse a sí mismo (Hitpael). Sentido reflexivo del Hitpael de ceñirse en preparación para la batalla o una acción decisiva. En el Salmo 93:1, el SEÑOR se ha ceñido de fortaleza, estableciendo el mundo de manera inmovible; aquí el reflexivo transmite auto-equipamiento soberano. Isaías 8:9 (repetido para énfasis) desafía a las naciones a ''ceñíos'', pero la cláusula siguiente promete que serán quebrantadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80860, 'spa', 'Ceñir, atar (Qal)', 'Ceñir, atar (Qal). Sentido transitivo y pasivo básico del Qal de ceñir o atar físicamente algo. En Job 38:3 y 40:7, Dios ordena a Job ''ciñe tus lomos'', un llamado a la disposición que todas las traducciones principales vierten literalmente. El participio pasivo en 2 R 1:8 describe a Elías como ''ceñido con un cinturón de cuero'', mientras que 1 Sam 2:4 extiende la imagen figuradamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80861, 'spa', 'Ser ceñido (Nifal)', 'Ser ceñido (Nifal). Sentido pasivo del Nifal que describe el estado de estar ya ceñido o equipado. Aparece solo en el Salmo 65:6, donde representa a Dios como ''ceñido de poder'', una descripción participial de su atributo permanente más que un acto único. La construcción pasiva lo distingue del ceñir activo de las otras conjugaciones, retratando el poder divino como algo permanentemente revestido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80864, 'spa', 'Ceñir de fuerza (Piel)', 'Ceñir de fuerza (Piel). Sentido intensivo del Piel de ceñir a alguien con fuerza, armadura o capacidad para la acción. Dios es el sujeto típico: en 2 Sam 22:40 y Sal 18:39, Él ciñe a David de fuerza para la batalla; en Sal 30:11, el duelo se cambia por alegría mientras Dios ciñe al salmista de gozo. Isaías 45:5 extiende esto a Ciro, a quien Dios ciñó sin que este lo conociera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80874, 'spa', 'Persona nativa', 'Persona nativa. Persona nacida en la tierra, ciudadano nativo con plena membresía en la comunidad del pacto. Los textos legales emparejan este término con גֵּר (forastero) para establecer igualdad de condiciones ante la ley (Éx 12:19, 48-49; Lv 16:29; 24:16, 22; Nm 15:13, 29-30). Transmite el arraigo cívico y étnico de quien ha ''brotado'' del suelo de la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80884, 'spa', 'Planta autóctona', 'Planta autóctona. Árbol o planta que crece en su suelo nativo, usado figuradamente en el Salmo 37:35 para describir al impío floreciendo como un árbol autóctono de raíces profundas. La imagen de crecimiento exuberante e incontrolado constituye una metáfora tomada directamente del sentido agrícola de ''brotar de la tierra''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80885, 'spa', 'Gentilicio ezraíta', 'Las traducciones conservan el gentilicio: español «el ezraíta», francés «l''Ezrahite», alemán con formas similares. 1 Reyes 4:31 cita a «Etán el ezraíta» como referente de sabiduría superado solo por Salomón. Los Salmos 88 y 89 atribuyen sus composiciones a Hemán y Etán «el ezraíta», vinculando sabiduría, música y el linaje de Zéraj.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80887, 'spa', 'hermano (consanguíneo)', 'Un hermano literal que comparte uno o ambos progenitores: el sentido primario de parentesco que abarca hermanos de padre y madre, medio hermanos y hermanos en general. Domina con 573 ocurrencias, desde Caín y Abel (Gn 4:9) hasta los hijos de Jacob y las genealogías tribales (1 Cr 5:7; 15:5). Universalmente traducido como hermano, frère, Bruder.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80893, 'spa', 'pariente, compatriota', 'Sentido relacional más amplio que se extiende más allá de la sangre para abarcar parientes tribales, connacionales israelitas o hermanos de pacto. Las glosas árabes favorecen إخوان (cofrades) sobre أخ (hermano) en estos contextos. Se emplea cuando Moisés arbitra entre ''hermanos'' israelitas (Dt 1:16) y cuando los levitas sirven junto a sus ''hermanos'' sacerdotes (Nm 18:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (80989, 'spa', 'Brasero portátil', 'El término aparece exclusivamente en el dramático relato donde el rey se sienta frente a un brasero encendido en sus aposentos de invierno. A medida que se lee cada sección del rollo de Jeremías, Joacim la corta y la arroja al fuego hasta consumir el rollo entero. Las repetidas menciones al fuego en el brasero resaltan tanto el calor literal que proporcionaba como su trágico papel como instrumento de destrucción de la palabra divina.');